Expand-Archive "$env:USERPROFILE\Downloads\handoff.zip" -DestinationPath "$env:TEMP\gw" -Force; $src = if (Test-Path "$env:TEMP\gw\handoff") { "$env:TEMP\gw\handoff\*" } else { "$env:TEMP\gw\*" }; Copy-Item $src -Destination . -Recurse -Force; Remove-Item "$env:TEMP\gw" -Recurse -Force; npm run build; if ($?) { git add -A; git commit -m "2026 brand: logo, hero timeline, press kit, blog grid, footer" }
